function getKoreaWeekStart(date = new Date()) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit",
  }).formatToParts(date);
  const value = (type) => Number(parts.find((part) => part.type === type)?.value);
  const midnightUtc = Date.UTC(value("year"), value("month") - 1, value("day"));
  const sundayUtc = midnightUtc - new Date(midnightUtc).getUTCDay() * 24 * 60 * 60 * 1000;
  return new Date(sundayUtc).toISOString().slice(0, 10);
}

function getKoreaToday(date = new Date()) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit",
  }).formatToParts(date);
  const value = (type) => parts.find((part) => part.type === type)?.value;
  return `${value("year")}-${value("month")}-${value("day")}`;
}

