function dataUrlToBlob(dataUrl) {
  const [header, encoded] = dataUrl.split(",");
  const mime = header.match(/data:(.*?);/)?.[1] || "image/jpeg";
  const bytes = atob(encoded);
  const data = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) data[i] = bytes.charCodeAt(i);
  return new Blob([data], { type: mime });
}

async function uploadImage(dataUrl, path) {
  const { error } = await supabase.storage.from("photos").upload(path, dataUrlToBlob(dataUrl), {
    contentType: "image/jpeg",
    upsert: false,
  });
  throwIfError(error);
  return supabase.storage.from("photos").getPublicUrl(path).data.publicUrl;
}

async function downloadImage(url, filename) {
  const response = await fetch(url);
  if (!response.ok) throw new Error("이미지를 내려받지 못했어요.");
  const blob = await response.blob();
  const objectUrl = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = objectUrl;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
}

// ---------- image helpers ----------

function cropToSquareDataURL(file, { zoom = 1, offsetX = 0, offsetY = 0, size = 2048, quality = 0.92 } = {}) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext("2d");
        const minSide = Math.min(img.width, img.height);
        const cropSide = minSide / zoom;
        const maxX = Math.max(0, (img.width - cropSide) / 2);
        const maxY = Math.max(0, (img.height - cropSide) / 2);
        const sx = Math.max(0, Math.min(img.width - cropSide, (img.width - cropSide) / 2 + offsetX * maxX));
        const sy = Math.max(0, Math.min(img.height - cropSide, (img.height - cropSide) / 2 + offsetY * maxY));
        ctx.drawImage(img, sx, sy, cropSide, cropSide, 0, 0, size, size);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const im = new Image();
    // Supabase Storage images are cross-origin. Set this before `src` so
    // images can safely be drawn into the archive canvas and exported.
    im.crossOrigin = "anonymous";
    im.onload = () => resolve(im);
    im.onerror = reject;
    im.src = src;
  });
}

async function composeGrid(themes) {
  const cols = 6, rows = 6;
  const canvas = document.createElement("canvas");
  canvas.width = cols * GRID_CELL;
  canvas.height = rows * GRID_CELL;
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "#1A1A1A";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const cells = [];
  themes.forEach((t) => {
    cells.push(t.photos.user1);
    cells.push(t.photos.user2);
  });

  for (let i = 0; i < cells.length; i++) {
    const src = cells[i];
    if (!src) continue;
    const img = await loadImage(src);
    const col = i % cols;
    const row = Math.floor(i / cols);
    ctx.drawImage(img, col * GRID_CELL, row * GRID_CELL, GRID_CELL, GRID_CELL);
  }
  return canvas.toDataURL("image/jpeg", 0.85);
}

async function rollOverWeekIfNeeded(state, archive) {
  const week = state.currentWeek;
  const thisSunday = getKoreaWeekStart();
  if (!week || week.startDate === thisSunday) return { state, archive, changed: false };

  const filled = week.themes.reduce(
    (total, theme) => total + (theme.photos.user1 ? 1 : 0) + (theme.photos.user2 ? 1 : 0),
    0
  );
  let nextArchive = archive;

  // Every Sunday starts a fresh current week. We keep a snapshot for the
  // "저번 주" strip, while the archive tab filters out incomplete snapshots.
    if (filled > 0) {
      const snapshotId = `${week.id}-${week.startDate}`;
      if (!archive.some((item) => item.weekId === snapshotId)) {
        try {
          const gridDataUrl = await composeGrid(week.themes);
          const gridImage = await uploadImage(gridDataUrl, `grids/${snapshotId}.jpg`);
          nextArchive = [
            ...archive,
            {
              weekId: snapshotId,
              startDate: week.startDate,
              gridImage,
              themeTexts: week.themes.map((theme) => theme.text),
            },
          ];
        } catch (error) {
          // A stale/broken cross-origin image must not block the entire app
          // from loading. The archive snapshot can be retried next boundary.
          console.error("[photo-journal] 아카이브 그리드 생성 실패", error);
        }
      }
    }

  return {
    state: { ...state, currentWeek: createNewWeek(state.themePool) },
    archive: nextArchive,
    changed: true,
  };
}

// ---------- theme pool logic ----------

function drawTheme(pool, usedIdsThisWeek) {
  if (pool.length === 0) return null;
  let candidates = pool.filter((p) => !usedIdsThisWeek.includes(p.id));
  if (candidates.length === 0) candidates = pool;
  return candidates[Math.floor(Math.random() * candidates.length)];
}

function createNewWeek(pool) {
  const startDate = getKoreaWeekStart();
  const id = "w" + Date.now();
  const first = drawTheme(pool, []);
  return {
    id,
    startDate,
    themes: first
      ? [{ themeId: first.id, text: first.text, photos: { user1: null, user2: null } }]
      : [],
  };
}

function advanceWeek(week, pool) {
  const usedIds = week.themes.map((t) => t.themeId);
  const next = drawTheme(pool, usedIds);
  if (!next) return week;
  return {
    ...week,
    themes: [
      ...week.themes,
      { themeId: next.id, text: next.text, photos: { user1: null, user2: null } },
    ],
  };
}

function defaultAppState() {
  return {
    slots: { user1: { name: "", code: "" }, user2: { name: "", code: "" } },
    themePool: DEFAULT_THEMES.map((t, i) => ({ id: "t" + i, text: t, addedBy: null })),
    currentWeek: null,
  };
}

// ---------- sample placeholder photos (for previewing the layout) ----------

function makeDummyPhoto(seed) {
  const size = 480;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  const grays = [224, 212, 198, 232, 206, 218, 192, 226, 208, 200];
  const base = grays[seed % grays.length];
  ctx.fillStyle = `rgb(${base},${base},${base})`;
  ctx.fillRect(0, 0, size, size);
  const cx = size * (0.3 + (0.4 * ((seed * 37) % 100)) / 100);
  const cy = size * (0.3 + (0.4 * ((seed * 53) % 100)) / 100);
  const delta = seed % 2 === 0 ? 20 : -20;
  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, size * 0.55);
  grad.addColorStop(0, `rgba(${base + delta},${base + delta},${base + delta},0.9)`);
  grad.addColorStop(1, `rgba(${base},${base},${base},0)`);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);
  return canvas.toDataURL("image/jpeg", 0.7);
}

// Builds a demo week: first 4 themes pre-filled with sample photos (so the
// horizontal strip has something to scroll through), plus one real, empty
// active theme so the person can start uploading right away.
function seedDemoWeek(pool) {
  const startDate = new Date().toISOString().slice(0, 10);
  const id = "w" + Date.now() + "-demo";
  const themes = [];
  const usedIds = [];
  let photoIndex = 0;
  for (let i = 0; i < 4; i++) {
    const t = drawTheme(pool, usedIds);
    if (!t) break;
    usedIds.push(t.id);
    themes.push({
      themeId: t.id,
      text: t.text,
      photos: { user1: makeDummyPhoto(photoIndex++), user2: makeDummyPhoto(photoIndex++) },
    });
  }
  const active = drawTheme(pool, usedIds);
  if (active) {
    themes.push({ themeId: active.id, text: active.text, photos: { user1: null, user2: null } });
  }
  return { id, startDate, themes };
}

// Builds 5 fully-filled demo archive entries (composited 6x6 grids) so the
// archive tab's featured layout (1 big + 4 small) has something to show.
async function seedDemoArchiveWeeks(count = 5) {
  const weeks = [];
  for (let w = 0; w < count; w++) {
    let idx = w * 40;
    const demoThemes = [];
    const themeTexts = [];
    for (let i = 0; i < WEEK_THEME_COUNT; i++) {
      demoThemes.push({ photos: { user1: makeDummyPhoto(idx++), user2: makeDummyPhoto(idx++) } });
      themeTexts.push(DEFAULT_THEMES[(w * WEEK_THEME_COUNT + i) % DEFAULT_THEMES.length]);
    }
    const gridImage = await composeGrid(demoThemes);
    const d = new Date();
    d.setDate(d.getDate() - 7 * (count - w));
    weeks.push({
      weekId: `w-demo-archive-${w}`,
      startDate: d.toISOString().slice(0, 10),
      gridImage,
      themeTexts,
    });
  }
  return weeks;
}

