function ModalPortal({ children }) {
  return typeof document === "undefined" ? null : createPortal(children, document.body);
}

function SaveImageButton({ src, filename, className, children }) {
  const [saving, setSaving] = useState(false);
  const handleSave = async () => {
    if (saving) return;
    setSaving(true);
    try {
      await downloadImage(src, filename);
    } catch (error) {
      console.error(error);
      alert("사진을 저장하지 못했어요. 인터넷 연결을 확인한 뒤 다시 시도해 주세요.");
    } finally {
      setSaving(false);
    }
  };
  return <button type="button" onClick={handleSave} disabled={saving} className={className}>{saving ? "저장 중..." : children}</button>;
}

