function CropModal({ file, onClose, onConfirm }) {
  const [zoom, setZoom] = useState(1);
  const [offsetX, setOffsetX] = useState(0);
  const [offsetY, setOffsetY] = useState(0);
  const [preview, setPreview] = useState("");
  const [saving, setSaving] = useState(false);
  const [comment, setComment] = useState("");

  useEffect(() => {
    let active = true;
    cropToSquareDataURL(file, { zoom, offsetX, offsetY, size: 720, quality: 0.88 })
      .then((value) => active && setPreview(value))
      .catch(() => active && setPreview(""));
    return () => { active = false; };
  }, [file, zoom, offsetX, offsetY]);

  const confirm = async () => {
    setSaving(true);
    try {
      const dataUrl = await cropToSquareDataURL(file, { zoom, offsetX, offsetY });
      await onConfirm(dataUrl, comment.trim());
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="jr-overlay" onClick={saving ? undefined : onClose}>
      <div className="jr-card max-w-sm w-full p-5 max-h-[calc(100dvh-24px)] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between gap-2 mb-1">
          <h3 className="jr-display text-xl">사진 자르기</h3>
          <button onClick={onClose} disabled={saving} className="jr-muted p-1"><X size={18} /></button>
        </div>
        <p className="jr-muted text-xs mb-4">정방형 틀 안에서 위치와 확대 정도를 조절해 주세요.</p>
        <div className="bg-[#1A1A1A] overflow-hidden rounded-md border jr-hairline mb-4 mx-auto" style={{ width: "min(100%, 38dvh)", height: "min(calc(100vw - 24px), 38dvh)" }}>
          {preview && <img src={preview} alt="선택한 사진 미리보기" className="w-full h-full object-cover" />}
        </div>
        <div className="space-y-3 text-xs jr-muted">
          <label className="block">확대
            <input aria-label="확대" type="range" min="1" max="3" step="0.05" value={zoom} onChange={(e) => setZoom(Number(e.target.value))} className="w-full mt-1" />
          </label>
          <label className="block">가로 위치
            <input aria-label="가로 위치" type="range" min="-1" max="1" step="0.02" value={offsetX} onChange={(e) => setOffsetX(Number(e.target.value))} className="w-full mt-1" />
          </label>
          <label className="block">세로 위치
            <input aria-label="세로 위치" type="range" min="-1" max="1" step="0.02" value={offsetY} onChange={(e) => setOffsetY(Number(e.target.value))} className="w-full mt-1" />
          </label>
        </div>
        <label className="jr-body text-xs block mt-4">사진 코멘트 <span className="jr-muted">(선택)</span>
          <textarea value={comment} onChange={(e) => setComment(e.target.value)} placeholder="이 사진에 남길 말을 적어 보세요." className="jr-input text-sm min-h-[76px] resize-none mt-1" maxLength={300} />
        </label>
        <div className="flex gap-2 mt-5">
          <button onClick={onClose} disabled={saving} className="jr-btn-ghost flex-1">취소</button>
          <button onClick={confirm} disabled={saving || !preview} className="jr-btn-primary flex-1">{saving ? "처리 중..." : "이대로 사용"}</button>
        </div>
      </div>
    </div>
  );
}

function WeekStrip({ themes, identity, uploading, onPick, roleNames, onUpdateComment }) {
  const stripRef = useRef(null);
  const activeCardRef = useRef(null);
  const activeIdx = themes.length - 1;
  const drag = useRef({ isDown: false, startX: 0, scrollLeft: 0, moved: false });
  const [viewingTheme, setViewingTheme] = useState(null);

  useEffect(() => {
    activeCardRef.current?.scrollIntoView({ behavior: "smooth", inline: "center", block: "nearest" });
  }, [themes.length]);

  const onMouseDown = (e) => {
    const el = stripRef.current;
    if (!el) return;
    drag.current = { isDown: true, startX: e.pageX, scrollLeft: el.scrollLeft, moved: false };
    el.style.cursor = "grabbing";
  };
  const onMouseMove = (e) => {
    if (!drag.current.isDown) return;
    const el = stripRef.current;
    if (!el) return;
    const dx = e.pageX - drag.current.startX;
    if (Math.abs(dx) > 3) drag.current.moved = true;
    el.scrollLeft = drag.current.scrollLeft - dx;
  };
  const endDrag = () => {
    drag.current.isDown = false;
    if (stripRef.current) stripRef.current.style.cursor = "grab";
  };
  const openTheme = (theme) => {
    if (drag.current.moved) return;
    setViewingTheme(theme);
  };

  return (
    <div className="mb-6">
      <div className="text-center mb-4">
        <p className="jr-eyebrow" style={{ fontFamily: "'MaruBuri','Gowun Batang',serif" }}>이번 주</p>
        <h2 className="jr-display jr-hand text-2xl mt-1">기록</h2>
      </div>
      <div
        ref={stripRef}
        className="jr-strip flex gap-3 overflow-x-auto px-1 py-1"
        style={{ cursor: "grab" }}
        onMouseDown={onMouseDown}
        onMouseMove={onMouseMove}
        onMouseUp={endDrag}
        onMouseLeave={endDrag}
      >
        {themes.map((t, i) =>
          i === activeIdx ? (
            <UploadCard
              key={t.themeId}
              cardRef={activeCardRef}
              theme={t}
              identity={identity}
              uploading={uploading}
              onPick={onPick}
              roleNames={roleNames}
              onUpdateComment={onUpdateComment}
            />
          ) : (
            <ThemeCard key={t.themeId} theme={t} onOpen={() => openTheme(t)} />
          )
        )}
      </div>
      {viewingTheme && (
        <ThemeViewModal theme={viewingTheme} roleNames={roleNames} onUpdateComment={onUpdateComment} onClose={() => setViewingTheme(null)} />
      )}
    </div>
  );
}

